                s = s.Replace("Mr Naruhodo! He's talking about Dr Sithe!", "Monsieur Naruhodo ! Il parle de la Dre Pétrie !");
                s = s.Replace("Ah!\r\n(Of course...)", "Ah !\r\n(Évidemment...)");
                s = s.Replace("I'm, I'm terribly sorry about that.\r\nI was just, um...", "J-Je suis sincèrement désolé.\r\nJ'étais juste, euh...");
                s = s.Replace("Fear not. You've done nothing wrong.\r\nDr Sithe's own wrongdoing precipitated the situation.", "Ne craignez rien. Vous n'avez rien à vous reprocher.\r\nC'est la propre turpitude de la Dre Pétrie qui a précipité cette issue.");
                s = s.Replace("You needn't concern yourself with it any further.", "Vous n'avez plus à vous en préoccuper.");
                s = s.Replace("(That would be a lot easier to do if it weren't for the\r\npiercing stare you're giving me...)", "(Ce serait bien plus aisé si vous n'aviez pas ce regard perçant braqué sur moi...)");
                s = s.Replace("Lord van Zieks is doing an admirable job of holding the\r\nfort.", "Lord Van Peers fait un travail admirable pour tenir la barre.");
                s = s.Replace("Though disturbingly, his apprentice has been missing\r\nsince yesterday.", "Quoique de manière inquiétante, son apprenti a disparu depuis hier.");
                s = s.Replace("O-Oh...\r\n(Missing...?)", "O-Oh...\r\n(Disparu...?)");
                s = s.Replace("What's become of Kazuma-sama now...?", "Qu'est-il donc arrivé à Monsieur Kiyô... ?");
                return s;
            };

