            entryTranslators[@"BB\script\output\_sce03_c001_0020_eng#6"] = (en) => {
                string s = en;
                s = s.Replace("Uèèè uèèèèèèèèèèèè!\r\nBut you are always scared of the dark!", "Ouaïïï ouaïïïïïïïïïïïï !\r\nMais tu as toujours peur du noir !");
                s = s.Replace("Shut your mouth, you idiot! I will sit quietly in ze dark\r\nand plan our next daring 'eist!", "Ferme ta boîte, imbécile ! Je vais m'asseoir dans le noir\r\net planifier notre prochain casse héroïque !");
                s = s.Replace("Uèèèèèèèèèèèèèèèèèèèèèèèèèèè!\r\nI don't-a like this! I don't-a like it!", "Ouaïïïïïïïïïïïïïïïïïïïïïïïïïïï !\r\nJ'aime pas ça ! J'aime pas du tout !");
                s = s.Replace("Well tough! We'll finish this down the Yard!\r\nNow get movin'!", "Tant pis pour vous ! On réglera ça au Yard !\r\nEn route, maintenant !");
                s = s.Replace("Bye then, Ginny!\r\nHave fun!", "Au revoir alors, Ginny !\r\nAmuse-toi bien !");
                s = s.Replace("Oh yeah, thanks, Iris!\r\nAnd thanks... ya great detective!", "Ah ouais, merci Iris !\r\nEt merci... grand détective !");
                s = s.Replace("Heehee! Gina makes a fine detective herself, doesn't she?", "Héhé ! Gina fait un remarquable détective elle-même, non ?");
                s = s.Replace("Oh, Susie! And Runo!", "Oh, Susette ! Et Yûno !");
                s = s.Replace("Hello, Iris. We're home!", "Bonjour, Iris. Nous voilà rentrés !");
                s = s.Replace("Well? Did you find your daddy?", "Alors ? Tu as trouvé ton papa ?");
                s = s.Replace("Yes! We arrived at the hotel just before he and his friend.", "Oui ! Nous sommes arrivés à l'hôtel juste avant lui et son ami.");
                s = s.Replace("Oh! Well that's great news.\r\nI hope I'll get to see my daddy again soon...", "Oh ! Quelle excellente nouvelle.\r\nJ'espère que je pourrai revoir mon papa bientôt...");
                s = s.Replace("Ah...yes...of course...", "Ah... oui... bien sûr...");
                s = s.Replace("(Dr John H. Wilson...)", "(Le Dr John H. Wilson...)");
                s = s.Replace("So, Iris! All that remains now is that\r\ngreatest of problems known to man!", "Alors, Iris ! Il ne nous reste plus que le\r\nplus grand problème connu de l'humanité !");
                s = s.Replace("But before we concern ourselves with that, I believe\r\nsome tea is in order, don't you, my dear fellows?", "Mais avant de nous en soucier, je crois qu'une tasse de thé s'impose, n'est-ce pas, mes chers amis ?");
                s = s.Replace("Is something wrong, Mr Naruhodo?", "Un problème, Monsieur Naruhodo ?");
                s = s.Replace("Do I have a crumb or suchlike on my face?", "Ai-je une miette ou quelque chose sur le visage ?");
                s = s.Replace("Uh...\r\n(Not so much on your face...)", "Euh...\r\n(Pas tant sur votre visage...)");
                s = s.Replace("(...as on your head, I'd say.)", "(... que sur votre tête, je dirais.)");
                s = s.Replace("Come along then, everyone. I've brewed a lovely special\r\nblend. Time for tea!", "Venez tous alors. J'ai préparé un délicieux mélange maison. C'est l'heure du thé !");
                s = s.Replace("Whatever is going on here today?", "Que se passe-t-il donc ici aujourd'hui ?");
                s = s.Replace("In that case, let us sit and drink now.", "En ce cas, asseyons-nous et buvons.");
                s = s.Replace("For I am in fact expecting a guest later today.", "Car j'attends une visite plus tard dans la journée.");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c001_0030_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("Mr Sholmes, you mentioned before...\r\n...that you were expecting a guest today?", "Monsieur Holmes, vous disiez tout à l'heure...\r\n... que vous attendiez une visite aujourd'hui ?");
                s = s.Replace("Indeed, Miss Susato, that is correct.", "Tout à fait, Mademoiselle Susato, c'est exact.");
                s = s.Replace("Not another of those red-headed gentlemen that were\r\nhere before?", "Pas un autre de ces messieurs aux cheveux roux de tout à l'heure ?");
                s = s.Replace("Not at all. They were petty villains.", "Pas du tout. C'étaient de petits vauriens.");
                s = s.Replace("The guest I am expecting is a client.", "La personne que j'attends est un client.");
                s = s.Replace("A young gentlewoman who wishes to appoint the services\r\nof this great detective, no less!", "Une jeune dame de qualité qui requiert les services de ce grand détective, rien de moins !");
                s = s.Replace("Oh, how wonderful, Mr Sholmes!", "Oh, formidable, Monsieur Holmes !");
                s = s.Replace("You must stay and observe the fashion in which a great\r\ndetective receives his customers.", "Vous devez rester pour observer la manière dont un grand détective reçoit ses clients.");
                s = s.Replace("...Must we?", "... Sommes-nous vraiment obligés ?");
                s = s.Replace("I have you in my clutches now, rent!\r\nJust as I have you in my clutches, red-heads!", "Je te tiens entre mes griffes désormais, loyer !\r\nTout comme je vous tiens entre mes griffes, les rouquins !");
                s = s.Replace("Ah ha ha ha ha ha ha ha ha hah!", "Ah ha ha ha ha ha ha ha ha hah !");
                s = s.Replace("...That hearty laugh is masking rather sinister thoughts,\r\nI feel.", "... J'ai l'impression que ce rire jovial dissimule de bien sombres pensées.");
                s = s.Replace("You know, the lady isn't due for another hour yet.", "Vous savez, cette dame ne doit arriver que dans une heure.");
                s = s.Replace("Don't feel as though you must wait around if you have\r\nother things to do.", "Ne vous sentez pas obligés d'attendre si vous avez d'autres choses à faire.");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c001_0040_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("*Ding-aling-aling*", "*Drelin-drelin-drelin*");
                s = s.Replace("Aha! Here is my guest now.\r\nMy latest client! With money to spend!", "Aha ! Voici mon invitée.\r\nMa nouvelle cliente ! Avec de quoi payer !");
                s = s.Replace("Ooh, I do hope it's an exciting case, Hurley!", "Ooh, j'espère que c'est une affaire palpitante, Sherlockinou !");
                s = s.Replace("Remember, Iris, we are at present gripped by the greatest\r\nproblem known to man.", "Rappelle-toi, Iris, que nous sommes actuellement en proie au plus grand problème connu de l'humanité.");
                s = s.Replace("I must be willing to accept any case, no matter how\r\nunstimulating. Save locating a runaway, of course.", "Je dois être prêt à accepter n'importe quelle affaire, aussi peu stimulante soit-elle. Sauf retrouver un fugitif, évidemment.");
                s = s.Replace("...Don't spare anyone's feelings, will you?", "... N'ayez aucun ménagement pour les sentiments d'autrui, surtout.");
                s = s.Replace("Oh dear... I'm afraid that Hurley can lack a little tact,\r\nespecially just before the rent is due.", "Misère... J'ai bien peur que Sherlockinou manque parfois d'un peu de tact, surtout juste avant l'échéance du loyer.");
                s = s.Replace("*Thwack!*", "*Vlan !*");
                s = s.Replace("Mr Sholmes! Mr Herlock Sholmes!\r\nPlease... Oh, please...", "Monsieur Holmes ! Monsieur Sherlock Holmes !\r\nDe grâce... Oh, je vous en supplie...");
                s = s.Replace("...please find my husband!\r\nHe's run away!", "... retrouvez mon mari !\r\nIl s'est enfui !");
                s = s.Replace("To upset me?", "Pour me contrarier ?");
                s = s.Replace("I beg your pardon?", "Pardonnez-moi ?");
                s = s.Replace("Never mind. A personal matter.\r\nMy apologies.", "Peu importe. Une affaire personnelle.\r\nMes excuses.");
                s = s.Replace("What exactly are you trying to say, Mr Naruhodo?", "Qu'essayez-vous d'insinuer exactement, Monsieur Naruhodo ?");
                s = s.Replace("...I didn't say a word.", "... Je n'ai pas dit un mot.");
                s = s.Replace("Come, my dear madam, be seated.\r\nIris, some tea, if you please?", "Venez, ma chère dame, prenez place.\r\nIris, du thé, s'il te plaît ?");
                s = s.Replace("Of course!", "Tout de suite !");
                s = s.Replace("What's the matter, Miss Susato?", "Qu'y a-t-il, Mademoiselle Susato ?");
                s = s.Replace("Oh, it's... it's just that gentlewoman...", "Oh, c'est... c'est cette dame...");
                s = s.Replace("I feel sure I've seen her somewhere before.\r\nVery recently.", "J'ai la certitude de l'avoir déjà vue quelque part.\r\nTrès récemment.");
                s = s.Replace("(...! Yes, now you come to mention it...)", "(! Oui, maintenant que vous le dites...)");
                s = s.Replace("As I explained earlier, my name is Evie Vigil.", "Comme je l'expliquais plus tôt, mon nom est Evie Vigil.");
                s = s.Replace("I implore you to take the case, sir!\r\nMoney is no object. Simply name your figure!", "Je vous supplie d'accepter cette affaire, monsieur !\r\nL'argent n'est pas un obstacle. Fixez votre prix !");
                s = s.Replace("Money and wealth are of little consequence to me,\r\nmadam.", "L'argent et la fortune sont de peu d'importance pour moi, madame.");
                s = s.Replace("Being offered a case to solve is reward enough.", "Qu'on m'offre une énigme à résoudre est une récompense suffisante.");
                s = s.Replace("Oh, Mr Sholmes!\r\nYou are the picture of benevolence!", "Oh, Monsieur Holmes !\r\nVous êtes la bonté même !");
                s = s.Replace("I will of course make a mental note of your offer,\r\nhowever. For...contingent reasons.", "Je prends toutefois bonne note de votre offre, naturellement. Pour... des raisons contingentes.");
                s = s.Replace("I trust you will remember your words also.", "J'ose espérer que vous vous souviendrez aussi de vos paroles.");
                s = s.Replace("Um... if I might enquire, sir...\r\n...this gentleman and lady would be...?", "Euh... si je puis me permettre, monsieur...\r\n... ce monsieur et cette demoiselle sont... ?");
                s = s.Replace("Oh! Um...me?", "Oh ! Euh... moi ?");
                s = s.Replace("What I am about to tell you, I should like to communicate\r\nin the strictest confidence, you understand.", "Ce que je m'apprête à vous confier, j'aimerais le faire dans la plus stricte confidentialité, comprenez-vous.");
                s = s.Replace("Ah, these are my friends.\r\nI assure you, you may say before this pair anything which\r\nyou may say to me.", "Ah, ce sont mes amis.\r\nJe vous garantis que vous pouvez énoncer devant ce duo tout ce que vous pourriez me confier à moi.");
                s = s.Replace("Ah...I see...", "Ah... je vois...");
                s = s.Replace("I can vouch for the gentleman personally.\r\nAfter all... ...he's hard of hearing.", "Je peux me porter garant du monsieur personnellement.\r\nAprès tout... il est dur d'oreille.");
                s = s.Replace("(...Why did I ever get my hopes up?)", "(... Pourquoi ai-je osé espérer quoi que ce soit ?)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c001_0060_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("Thank you for everything you have shared with us,\r\nMrs Vigil.", "Merci pour toutes ces précisions,\r\nMadame Vigil.");
                s = s.Replace("I believe I have all the information I need to begin my\r\ninvestigation.", "J'estime détenir tous les éléments nécessaires pour débuter mes investigations.");
                s = s.Replace("Oh, please report to me soon with good news, sir!", "Oh, j'espère que vous m'apporterez de bonnes nouvelles très vite, monsieur !");
                s = s.Replace("Fear not, madam.\r\nIn a day or two, I shall be contacting you with a\r\nheartening report, I'm quite sure.", "Soyez sans crainte, madame.\r\nD'ici un jour ou deux, je vous recontacterai avec des conclusions des plus réjouissantes, j'en suis persuadé.");
                s = s.Replace("So soon?\r\nOh, how splendid, Mr Sholmes!", "Si vite ?\r\nOh, merveilleux, Monsieur Holmes !");
                s = s.Replace("Good news should be delivered early, I always say.\r\nIf you would be so kind as to leave the photograph of your\r\nhusband in my possession...?", "Les bonnes nouvelles ne doivent pas attendre, comme je le répète toujours.\r\nSi vous aviez l'amabilité de me confier la photographie de votre époux... ?");
                s = s.Replace("The photograph of Mr Vigil has been\r\nentered into the Court Record.", "La photographie de M. Vigil a été ajoutée\r\nau dossier de l'affaire.");
                s = s.Replace("Thank you. Now, allow me to show you the door.", "Merci. À présent, permettez-moi de vous raccompagner jusqu'à la sortie.");
                s = s.Replace("I can't thank you enough, Mr Sholmes.\r\nYou've been simply marvellous!", "Je ne vous remercierai jamais assez, Monsieur Holmes.\r\nVous avez été tout bonnement admirable !");
                s = s.Replace("You know, I think it every time, Hurley...\r\n...but how do you come out with such nonsense?", "Tu sais, je me fais la réflexion à chaque fois, Sherlockinou...\r\n... mais comment fais-tu pour raconter de tels bobards ?");
                s = s.Replace("Good news in a day or two?\r\nAre you sure?", "Des bonnes nouvelles d'ici un jour ou deux ?\r\nTu en es bien sûr ?");
                s = s.Replace("I can't be sure, of course.\r\nBut then I didn't swear on it.", "Je n'en suis pas certain, évidemment.\r\nMais je n'ai pas prêté serment.");
                s = s.Replace("I merely gave the good woman some hope. I hope to be\r\nable to give her good news, one might say.", "J'ai simplement donné un peu d'espoir à cette brave dame. J'espère être en mesure de lui apporter de bonnes nouvelles, pourrait-on dire.");
                s = s.Replace("After all, the rent must be paid by the end of day\r\ntomorrow.", "Après tout, le loyer doit être acquitté avant demain soir.");
                s = s.Replace("If by that time I've successfully located Mr Vigil, we shall\r\nbe mutually relieved.", "Si d'ici là j'ai localisé avec succès M. Vigil, nous serons mutuellement soulagés.");
                s = s.Replace("Wouldn't you agree, Mr Naruhodo?", "N'êtes-vous pas de cet avis, Monsieur Naruhodo ?");
                s = s.Replace("...Don't look at me with those pleading eyes.", "... Ne me regardez pas avec ces yeux de chien battu.");
                s = s.Replace("Well, my dear fellow? Did you hear the details of the\r\ncase?", "Alors, mon cher ami ? Avez-vous entendu les détails de l'affaire ?");
                s = s.Replace("Yes... my hearing is surprisingly good, actually.", "Oui... mon ouïe est étonnamment affûtée, en réalité.");
                s = s.Replace("Excellent!\r\nAnd what did you make of it?", "Parfait !\r\nEt qu'en avez-vous pensé ?");
                s = s.Replace("Well, I was surprised to learn where her husband\r\nworked. At Barclay Prison, I mean...", "Eh bien, j'ai été surpris d'apprendre où son mari travaillait. À la prison de Barclay, je veux dire...");
                s = s.Replace("Ah, so you noted that?", "Ah, vous avez donc relevé ce détail ?");
                s = s.Replace("Of course. Especially with the mention of Lowgate\r\nCemetery...", "Bien sûr. Surtout avec la mention du cimetière de Lowgate...");
                s = s.Replace("Lowgate Cemetery is at the rear of Barclay Prison.\r\nSo it was renowned among us students at the university\r\nfor being haunted by the ghosts of condemned convicts.", "Le cimetière de Lowgate se trouve à l'arrière de la prison de Barclay.\r\nC'est pourquoi il était réputé parmi nous autres étudiants de l'université pour être hanté par les spectres des condamnés à mort.");
                s = s.Replace("Barclay Prison is where that notorious man was\r\nincarcerated!\r\nThe Professor...", "La prison de Barclay est l'endroit où ce sinistre individu était incarcéré !\r\nLe Démon Assassin...");
                s = s.Replace("And now a warder from the prison has mysteriously\r\ndisappeared, it would seem.\r\nIt's all very peculiar...", "Et voilà qu'un gardien de cette même prison a mystérieusement disparu, semblerait-il.\r\nTout cela est bien étrange...");
                s = s.Replace("Indeed. But nothing you can't handle, I'm quite certain,\r\nMr Naruhodo.", "En effet. Mais rien qui soit hors de votre portée, j'en suis tout à fait convaincu, Monsieur Naruhodo.");
                s = s.Replace("Sorry?\r\nRun along to the prison and see what you can glean,\r\nwould you?", "Pardon ?\r\nFilez donc jusqu'à la prison voir ce que vous pouvez glaner, voulez-vous ?");
                s = s.Replace("It's the prison governor you want.\r\nNo doubt the man is equally worried.", "C'est le directeur de la prison qu'il vous faut voir.\r\nNul doute que l'homme est tout aussi inquiet.");
                s = s.Replace("But... aren't you going to go yourself?", "Mais... vous n'allez pas y aller vous-même ?");
                s = s.Replace("Surely you needn't ask.\r\nI can't possibly be seen out with this hair!", "Avez-vous vraiment besoin de le demander ?\r\nJe ne peux décemment pas me montrer dehors avec ces cheveux-là !");
                s = s.Replace("...But didn't you go to Lime Street with that hair?", "... Mais n'êtes-vous pas allé à Lime Street avec cette chevelure ?");
                s = s.Replace("That was a quite different matter.\r\nSo, I leave it in your capable hands.\r\nNow, if you'll excuse me, I'm rather busy.", "C'était bien différent.\r\nBref, je vous confie l'affaire.\r\nÀ présent, si vous voulez bien m'excuser, je suis plutôt occupé.");
                s = s.Replace("(Of course you are...)", "(Évidemment que vous l'êtes...)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c002_0000_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("Barclay Prison is on the outskirts of London, \r\nbacking onto a lonely burial ground.", "La prison de Barclay se dresse à la périphérie de Londres,\r\nadossée à un sinistre champ de repos.");
                s = s.Replace("Its four high outer walls loomed \r\nquietly before us in the fog.", "Ses quatre hautes murailles extérieures se dressaient\r\nsilencieusement devant nous dans la brume.");
                s = s.Replace("Having requested a meeting, we were shown\r\nto the governor's office in the watchtower.", "Ayant sollicité une audience, nous fûmes conduits\r\nau bureau du directeur dans la tour de garde.");
                s = s.Replace("1st November\r\nBarclay Prison, Governor's Office", "1er novembre\r\nPrison de Barclay, Bureau du directeur");
                s = s.Replace("This place is full of hardened criminals. I cannae \r\nremember the last time a civilian was doon here.", "Cet endroit grouille de criminels endurcis. J'me rappelle pas\r\nla dernière fois qu'un civil a mis les pieds ici.");
                s = s.Replace("And you dinnae want to talk to an inmate, but to me?", "Et vous voulez point causer à un détenu, mais à moi ?");
                s = s.Replace("D'you ken who I am? I'm the governor, Barry Caidin...\r\nhm?", "Savez-vous à qui vous parlez ? J'suis le directeur, Barry Caidin...\r\nhein ?");
                s = s.Replace("Oh...yes...it's a pleasure.\r\nI'm Ryunosuke Naruhodo, defence lawyer.", "Oh... oui... enchanté.\r\nJe suis Ryunosuke Naruhodo, avocat de la défense.");
                s = s.Replace("And an Easterner, I see.\r\nDoes that mean...", "Et un Oriental, j'vois bien.\r\nÇa veut-y dire...");
                s = s.Replace("Yes, I'm a visiting student of law from the Empire of Japan.", "Oui, je suis un étudiant en droit invité venu de l'Empire du Japon.");
                s = s.Replace("Japan?!\r\nDid ye say Japan?", "Le Japon ?!\r\nVous avez dit le Japon ?");
                s = s.Replace("Um...yes?", "Euh... oui ?");
                s = s.Replace("Well there's no any of your kind in here, laddie!\r\nMaybe you should try the prison next door, eh?", "Eh ben y a point d'vos semblables ici, mon gars !\r\nFaudrait p't-être voir à la taule d'à côté, hein ?");
                s = s.Replace("I didn't notice another prison next door, sir...", "Je n'ai pas remarqué d'autre prison à côté, monsieur...");
                s = s.Replace("Anyway, we came to ask you some questions about–", "Bref, nous sommes venus vous poser quelques questions sur–");
                s = s.Replace("I dinnae like to be so direct, but...\r\n...I've no intention of speaking wi' the likes o' you\r\nsuspicious-looking Easterners.", "J'aime point être aussi direct, mais...\r\n... j'ai nulle intention d'tailler une bavette avec des Orientaux à l'allure aussi louche que vous.");
                s = s.Replace("Now get oot of my hair.", "Alors du balai !");
                s = s.Replace("(So as soon as he finds out that we're from Japan, he reacts\r\nlike this...)\r\n(That surely means...)", "(Dès qu'il apprend que nous venons du Japon, il réagit ainsi...)\r\n(Cela signifie sans doute...)");
                s = s.Replace("I think... it's because of the Professor case.", "Je pense... que c'est à cause de l'affaire du Démon Assassin.");
                s = s.Replace("You think so too?", "Vous le pensez aussi ?");
                s = s.Replace("(Ten years ago...)\r\n(...Genshin Asogi – also known as the Professor – was\r\nincarcerated at this prison.)\r\nAnd then, after his execution, he apparently re-emerged\r\nfrom his grave in the cemetery behind the prison.", "(Il y a dix ans...)\r\n(... Genshin Asogi – connu sous le nom du Démon Assassin – était\r\nincarcéré dans cette prison.)\r\nEt puis, après son exécution, il est semble-t-il réapparu\r\nde sa tombe dans le cimetière à l'arrière de la prison.");
                s = s.Replace("I, I might 'ave known!\r\nYou're sniffing around aboot that case, aren't ya?\r\nYou're agents, eh? Part of the Professor's great web, no\r\ndoubt.", "J-J'aurais dû m'en douter !\r\nVous venez fureter autour d'cette histoire, pas vrai ?\r\nVous êtes des sbires, hein ? Des complices de la clique du Démon Assassin, sans\r\nl'ombre d'un doute !");
                s = s.Replace("No! Not at all!\r\nWe're just–", "Non ! Pas du tout !\r\nNous voulons juste–");
                s = s.Replace("Get gone wi' ya!\r\nBefore I punch yer lights oot!", "Foutez l'camp !\r\nAvant que j'vous dévisse la tête !");
                s = s.Replace("We're going, we're going!", "On s'en va, on s'en va !");
                s = s.Replace("(Clearly the ghost of that killer still haunts this place...)\r\n(We're not going to get anywhere here.)\r\n(Unless we can somehow prove to this man that there's\r\nnothing suspicious about us...)", "(À l'évidence, le spectre de cet assassin hante toujours ces lieux...)\r\n(Nous n'arriverons à rien ici.)\r\n(À moins de prouver d'une manière ou d'une autre à cet homme que nous n'avons\r\nrien de suspect...)");
                s = s.Replace("Governor Caidin...", "Directeur Caidin...");
                s = s.Replace("What are you thinking, Miss Susato?", "À quoi pensez-vous, Mademoiselle Susato ?");
                s = s.Replace("I feel sure that name came up in conversation recently\r\nsomewhere.\r\nI was wondering if whoever mentioned him might have\r\nsome ideas to help us.", "J'ai la certitude que ce nom est venu sur le tapis récemment\r\nquelque part.\r\nJe me demandais si la personne qui l'a mentionné n'aurait pas\r\ndes pistes pour nous aider.");
                s = s.Replace("(Come to think of it, I have the same feeling...)", "(À la réflexion, j'ai exactement la même impression...)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c002_0020_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("...I cannae tell you anything else.", "... J'peux rien vous dire de plus.");
                s = s.Replace("Thank you so much for your time, Governor.", "Merci infiniment pour votre temps, Directeur.");
                s = s.Replace("Oh, one moment afore you're away, hen...", "Oh, une minute avant d'déguerpir, ma belle...");
                s = s.Replace("I'm sure I have it here somewhere...\r\nAh, found it. Here, take this as a wee souvenir of your\r\nvisit to the prison.", "J'suis sûr d'avoir ça dans un coin...\r\nAh, trouvé ! Tenez, gardez ça comme p'tit souvenir d'votre\r\nvisite chez nous.");
                s = s.Replace("What is it?", "Qu'est-ce que c'est ?");
                s = s.Replace("That's Vigil's dismissal notice.\r\nIt's ten years old now of course.", "C'est l'avis d'licenciement de Vigil.\r\nIl date de dix ans maintenant, bien sûr.");
                s = s.Replace("Oh my!\r\nAre you sure?", "Grands dieux !\r\nVous êtes bien sûr ?");
                s = s.Replace("Aye, it's no trouble at all.\r\nIt's no the original, mind.", "Ouais, sans façons.\r\nC'est point l'original, notez bien.");
                s = s.Replace("Vigil's dismissal notice has been\r\nentered into the Court Record.", "L'avis de licenciement de Vigil a été ajouté\r\nau dossier de l'affaire.");
                s = s.Replace("Thank you very much, Governor Caidin!", "Merci infiniment, Directeur Caidin !");
                s = s.Replace("Well in return...\r\n...do me a favour and never come back here.\r\nThat case is closed.", "Eh ben en échange...\r\n... faites-moi l'plaisir d'plus jamais r'mettre les pieds ici.\r\nCette affaire est classée.");
                s = s.Replace("Well, I think we ought to return to Baker Street for the\r\ntime being.", "Bien, je crois que nous devrions retourner à Baker Street pour le\r\nmoment.");
                s = s.Replace("Yes, I agree. We need to report back to Mr Sholmes with\r\nwhat we've found out about Mr Vigil.", "Oui, je suis d'accord. Nous devons faire notre rapport à Monsieur Holmes sur ce que nous avons découvert au sujet de M. Vigil.");
                s = s.Replace("(What will he tell Mrs Vigil, I wonder?)", "(Que va-t-il bien pouvoir dire à Mme Vigil, je me le demande ?)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c003_0000_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("1st November\r\nSholmes's Suite", "1er novembre\r\nAppartement de Holmes");
                s = s.Replace("We're back!", "Nous revoilà !");
