                s = s.Replace("I thought you'd be back before long, so I baked some\r\nscones for us all.", "Je pensais bien que vous ne tarderiez pas, alors j'ai préparé des\r\nscones pour tout le monde.");
                s = s.Replace("Ah! So that's what the delicious smell is.", "Ah ! C'est donc ça, cette délicieuse odeur.");
                s = s.Replace("Greetings, my dear fellows!", "Salutations, mes chers amis !");
                s = s.Replace("You've returned a good deal sooner than I was\r\nanticipating.", "Vous êtes de retour bien plus tôt que je ne l'escomptais.");
                s = s.Replace("Um... hello, Mr Sholmes.", "Euh... bonjour, Monsieur Holmes.");
                s = s.Replace("Hello, Mr... Sholmes...", "Bonjour, Monsieur... Holmes...");
                s = s.Replace("Say nothing. Your thoughts are written all over your faces\r\nin any case.", "N'en dites rien. Vos pensées se lisent sur vos visages\r\ncomme dans un livre ouvert de toute façon.");
                s = s.Replace("It turns out that it may have been advisable to test my\r\nhair colour restoration tonic before application.", "Il s'avère qu'il eût été judicieux de tester ma lotion réparatrice de couleur avant de l'appliquer.");
                s = s.Replace("Oh my...", "Grands dieux...");
                s = s.Replace("Pray, tell me. What of our warder friend? Have you garnered some new information?", "De grâce, dites-moi. Qu'en est-il de notre ami gardien ? Avez-vous glané de nouveaux renseignements ?");
                s = s.Replace("Oh, um...yes. Something very surprising, in fact.\r\nThough it's not a patch on your hair, to be honest.", "Oh, euh... oui. Quelque chose de fort surprenant, en vérité.\r\nMême si cela ne fait pas le poids face à vos cheveux, pour être honnête.");
                s = s.Replace("It most certainly isn't.\r\nBut still, we discovered that–", "Certainement pas.\r\nQuoi qu'il en soit, nous avons découvert que–");
                s = s.Replace("SHOOOOOOOOOLMES!!!", "HOOOOOOOOOLMES !!!");
                s = s.Replace("Drop everyfin', Sholmes!\r\nThis is more important!", "Laisse tomber tout l'reste, Holmes !\r\nY a plus important !");
                s = s.Replace("Gina?", "Gina ?");
                s = s.Replace("I, I can't Adam an' Eve it...\r\n*Sniff, sniff...*", "J-J'peux pas y croire...\r\n*Reniflement, reniflement...*");
                s = s.Replace("What's happened?", "Que s'est-il passé ?");
                s = s.Replace("Clearly a very grave matter indeed.\r\nFor Miss Lestrade made no mention of my hair\r\nwhatsoever.", "À n'en pas douter, une affaire de la plus extrême gravité.\r\nCar Mademoiselle Lestrade n'a fait absolument aucune mention de ma toison.");
                s = s.Replace("It's... it's the boss...", "C'est... c'est le patron...");
                s = s.Replace("What do you mean?\r\n(Inspector Gregson?)", "Que veux-tu dire ?\r\n(L'inspecteur Gregson ?)");
                s = s.Replace("The boss is... He's... He's dead.", "Le chef est... Il est... Il est mort.");
                s = s.Replace("What...?", "Quoi... ?");
                s = s.Replace("They, they just found 'is body.\r\nShot... wiv a pistol...", "I-Ils viennent d'trouver son corps.\r\nDescendu... au flingue...");
                s = s.Replace("WHAAAAAAAAAT?!", "QUOOOOOOOI ?!");
                s = s.Replace("But... but... Inspector Gregson?!", "Mais... mais... l'inspecteur Gregson ?!");
                s = s.Replace("(He was... murdered?!)", "(Il a été... assassiné ?!)");
                s = s.Replace("No... Not Gregsy...", "Non... Pas Gregounet...");
                s = s.Replace("Come in, my dear girl.\r\nTell us the whole story.", "Entre, ma chère petite.\r\nRaconte-nous tout.");
                s = s.Replace("*Sniff, sniff...*", "*Reniflement, reniflement...*");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c003_0020_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("Thank you for informing us, Miss Lestrade.\r\nThis really is most terrible news. I'm dreadfully sorry...", "Merci de nous avoir prévenus, Mademoiselle Lestrade.\r\nC'est véritablement une nouvelle épouvantable. Je suis profondément désolé...");
                s = s.Replace("Wot are you sayin' sorry for?\r\nYou didn't do nuffin'!", "Pourquoi tu t'excuses ?\r\nT'as rien fait de mal !");
                s = s.Replace("Well...anyway...", "Bon... bref...");
                s = s.Replace("...I'm takin' a cab over to the scene right now.", "... j'prends un fiacre pour aller sur les lieux tout d'suite.");
                s = s.Replace("Please come an' all! As soon as ya can!\r\nYou've gotta 'elp!", "Venez aussi, j'vous en prie ! Dès que vous pouvez !\r\nFaut nous aider !");
                s = s.Replace("It's a detective's lot to appear wherever some sinister plot\r\nhas unfolded. Little wonder we all look haggard.", "C'est le lot d'un détective de paraître partout où se trame une sinistre machination. Rien d'étonnant à ce que nous ayons tous l'air hagard.");
                s = s.Replace("Sometimes these things are almost too much for the\r\nnerves.", "Parfois ces drames sont presque au-dessus des forces nerveuses.");
                s = s.Replace("Mr Sholmes...", "Monsieur Holmes...");
                s = s.Replace("What use is there in being a great detective if I fail to see\r\nsomething like this coming, hm?!", "À quoi bon prétendre être un grand détective si je suis incapable d'anticiper un tel drame, hein ?!");
                s = s.Replace("How could I let this happen to Gregson?!\r\nTo Gregson...", "Comment ai-je pu laisser une chose pareille arriver à Gregson ?!\r\nÀ Gregson...");
                s = s.Replace("Mr Naruhodo, I shall leave at once to begin my\r\ninvestigations.", "Monsieur Naruhodo, je pars sur-le-champ entamer mes investigations.");
                s = s.Replace("Of course, yes.\r\nWe will, too.", "Bien sûr, oui.\r\nNous aussi.");
                s = s.Replace("It would be helpful...\r\n...if you could talk to Mr Reaper and see what you can\r\nglean.", "Il me serait précieux...\r\n... que vous alliez vous entretenir avec Lord Faucheur pour voir ce que vous pouvez apprendre.");
                s = s.Replace("I'm sure you were intending to do so anyway.\r\nUntil later, then!", "Je ne doute pas que c'était déjà votre intention de toute façon.\r\nÀ tout à l'heure, donc !");
                s = s.Replace("(Inspector Gregson, dead...\r\nAnd Lord van Zieks arrested...)", "(L'inspecteur Gregson, mort...\r\nEt Lord Van Peers arrêté...)");
                s = s.Replace("Runo! Susie!\r\nI've called you a hansom. It's waiting outside.", "Yûno ! Susette !\r\nJ'ai hélé un fiacre pour vous. Il attend dehors.");
                s = s.Replace("Thanks, Iris.\r\nShall we, Miss Susato?", "Merci, Iris.\r\nOn y va, Mademoiselle Susato ?");
                s = s.Replace("Yes!", "Oui !");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c003_0040_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("1st November\r\nLocal Prison, Cell 1", "1er novembre\r\nPrison locale, Cellule 1");
                s = s.Replace("(There he is.\r\nLord van Zieks behind bars...)", "(Le voilà.\r\nLord Van Peers derrière les barreaux...)");
                s = s.Replace("So it's true. He really was arrested...", "C'est donc vrai. Il a bel et bien été arrêté...");
                s = s.Replace("(He's sitting with his back to the wall, reading something.\r\nI don't think he's noticed us.)", "(Il est assis le dos au mur, en train de lire quelque chose.\r\nJe ne crois pas qu'il nous ait remarqués.)");
                s = s.Replace("Erm...\r\nLord van Zieks!", "Euh...\r\nLord Van Peers !");
                s = s.Replace("...Fancy meeting you here.", "... Quelle coïncidence de vous trouver là.");
                s = s.Replace("The last place on earth I'd like to be, with the last person\r\non earth I'd like to see.", "Le dernier endroit sur terre où je souhaiterais être, avec la dernière personne\r\nau monde que je souhaiterais voir.");
                s = s.Replace("...I couldn't very well not come.", "... Je ne pouvais décemment pas ne pas venir.");
                s = s.Replace("We heard what happened. That you...\r\nThat Inspector Gregson was...", "Nous avons appris ce qui s'est passé. Que vous...\r\nQue l'inspecteur Gregson a été...");
                s = s.Replace("Go home. This has nothing to do with you.", "Rentrez chez vous. Cela ne vous regarde en rien.");
                s = s.Replace("But...", "Mais...");
                s = s.Replace("Forgive me, Lord van Zieks, but I must disagree.", "Pardonnez-moi, Lord Van Peers, mais je ne puis être d'accord.");
                s = s.Replace("Inspector Gregson was very helpful to us on a number of\r\noccasions.", "L'inspecteur Gregson nous a été d'un grand secours à de multiples reprises.");
                s = s.Replace("We're indebted to him. At the very least we owe it to him\r\nto find out the truth about his death.", "Nous avons une dette envers lui. Au strict minimum, nous lui devons d'élucider la vérité sur sa disparition.");
                s = s.Replace("You must help us with our investigations, please!", "Vous devez nous aider dans nos investigations, je vous en prie !");
                s = s.Replace("There's really nothing I can tell you.", "Il n'y a véritablement rien que je puisse vous apprendre.");
                s = s.Replace("What were you just reading at the back of the cell there?", "Que lisiez-vous à l'instant au fond de votre cellule ?");
                s = s.Replace("Was it something related to the case?", "Était-ce en rapport avec l'affaire ?");
                s = s.Replace("...This?", "... Ceci ?");
                s = s.Replace("The Yard isn't quite so cavalier with its information as to\r\nshare case details with a suspect.", "Scotland Yard n'est pas frivole au point de communiquer les détails de l'affaire à un suspect.");
                s = s.Replace("This is... a letter from an old acquaintance.", "Il s'agit... d'une lettre d'une vieille connaissance.");
                s = s.Replace("Oh. Who might that be?", "Oh. Et de qui pourrait-il s'agir ?");
                s = s.Replace("Someone you know, as it happens.\r\nAlbert Harebrayne.", "Quelqu'un que vous connaissez, en l'occurrence.\r\nSamba Lonron.");
                s = s.Replace("(Of course, yes. I keep forgetting they went to the same\r\nuniversity.)", "(Bien sûr, oui. J'oublie sans cesse qu'ils fréquentaient la même université.)");
                s = s.Replace("And I would like to read my correspondence in peace.\r\nSo let's get this over with, shall we?", "Et j'aimerais lire mon courrier en paix.\r\nAlors en finissons au plus vite, voulez-vous ?");
                s = s.Replace("What is it you want to know?", "Qu'avez-vous à me demander ?");
                s = s.Replace("(Strange...)\r\n(I mean, let's face it, Lord van Zieks never minces his\r\nwords...)\r\n(...but they seem to have less bite than usual somehow.)", "(Étrange...)\r\n(Je veux dire, Lord Van Peers ne mâche jamais ses mots d'habitude...)\r\n(... mais ils semblent avoir moins de mordant qu'à l'accoutumée.)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c003_0050_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("So. It appears our conversation has run dry.", "Bien. Il semblerait que notre conversation soit tarie.");
                s = s.Replace("There was a two-second silence, that's all.", "Il y a juste eu deux secondes de silence, c'est tout.");
                s = s.Replace("Well in any event, if you'll excuse me now.\r\n...I wouldn't like to detain you.", "Quoi qu'il en soit, si vous voulez bien m'excuser.\r\n... Je ne voudrais point vous retenir plus longtemps.");
                s = s.Replace("I was wondering, Lord van Zieks...\r\nIf you'd like...", "Je me demandais, Lord Van Peers...\r\nSi vous le désirez...");
                s = s.Replace("...I'd be happy to advocate for you.", "... je serais honoré d'assurer votre défense.");
                s = s.Replace("...You trust me, do you?", "... Vous avez confiance en moi, vraiment ?");
                s = s.Replace("Yes.", "Oui.");
                s = s.Replace("I've heard you speak many times in court.\r\nI've seen how you treat people.", "Je vous ai entendu plaider à de multiples reprises.\r\nJ'ai vu la manière dont vous traitez les gens.");
                s = s.Replace("So I'm quite sure that you would never have taken\r\nanother's life.", "Je suis donc convaincu que vous n'auriez jamais ôté la vie d'autrui.");
                s = s.Replace("...It's just, my feelings can't be used as evidence in a court\r\nof law, sadly.", "... C'est seulement que mes sentiments ne peuvent servir de preuve devant un tribunal, hélas.");
                s = s.Replace("It's a very gracious offer. However...\r\n...I trust no one.", "C'est une proposition fort généreuse. Cependant...\r\n... je n'ai confiance en personne.");
                s = s.Replace("What?", "Comment ?");
                s = s.Replace("Not the police, not the judiciary... and not you Nipponese.", "Ni en la police, ni en la magistrature... et encore moins en vous autres Japonais.");
                s = s.Replace("But please...", "Mais de grâce...");
                s = s.Replace("I have no intention of engaging your services.", "Je n'ai nulle intention de recourir à vos services.");
                s = s.Replace("(The chasm between us is just too wide and too deep, it\r\nseems...)", "(Le gouffre entre nous est décidément trop large et trop profond, semblerait-il...)");
                s = s.Replace("...I'd appreciate it if you don't visit again.\r\nThen neither of us will waste any more time.", "... Je vous saurais gré de ne point revenir.\r\nAinsi, ni l'un ni l'autre ne perdrons davantage de temps.");
                s = s.Replace("(Perhaps we need to dig a little deeper...)\r\n(...and find out more about Lord van Zieks and what\r\nhappened to Inspector Gregson.)", "(Peut-être devons-nous creuser un peu plus profond...)\r\n(... et en apprendre davantage sur Lord Van Peers et ce qui est arrivé à l'inspecteur Gregson.)");
                return s;
            };

            entryTranslators[@"BB\script\output\_sce03_c003_0060_eng#2"] = (en) => {
                string s = en;
                s = s.Replace("1st November\r\nRoom on Fresno Street", "1er novembre\r\nChambre de Fresno Street");
                s = s.Replace("(This really is an out-of-the-way part of London. I doubt\r\nmany people find their way down this back street.)", "(C'est vraiment un quartier reculé de Londres. Je doute que beaucoup de gens s'aventurent dans cette ruelle.)");
                s = s.Replace("(So this dust-ridden rented old room is where it happened\r\nthen...)", "(C'est donc dans cette vieille chambre meublée poussiéreuse que le drame s'est produit...)");
                s = s.Replace("So this is... where poor Inspector Gregson lost his life.", "C'est donc ici... que le pauvre inspecteur Gregson a perdu la vie.");
                s = s.Replace("Yes... And the police are already hard at work\r\ninvestigating, it seems.", "Oui... Et la police s'active déjà à fouiller les lieux, semblerait-il.");
                s = s.Replace("(I don't see Mr Sholmes anywhere, though...)\r\n(Perhaps his investigations have taken him elsewhere.)", "(Je ne vois nulle part Monsieur Holmes, en revanche...)\r\n(Peut-être ses investigations l'ont-elles mené ailleurs.)");
                s = s.Replace("Oi! Wot d'ya think yer doin' there?!", "Hé ! Qu'est-ce que tu fabriques, toi ?!");
                s = s.Replace("Every one o' them drawers 'as gotta be taken right out so\r\nyou can look underneath an' all!", "Faut retirer chaque tiroir jusqu'au fond pour vérifier en dessous aussi !");
                s = s.Replace("I want the space above this ceilin' checked, and don't\r\nforget to look inside the chimney stack, too!", "J'veux qu'on fouille l'espace au-dessus du plafond, et oubliez pas d'regarder dans l'conduit de cheminée !");
                s = s.Replace("Blimey! Ain't you lot never gone over an 'ouse lookin' for\r\ndough when the owners are out o' town?", "Bon sang ! Vous avez jamais retourné une baraque pour trouver du flouze quand les proprios sont partis en vadrouille ou quoi ?");
                s = s.Replace("(Gina's obviously got some unique investigative\r\ntechniques she wants everyone to adopt...)", "(Gina a visiblement des méthodes d'investigation bien à elle qu'elle veut imposer à tout le monde...)");
                s = s.Replace("Oh, so you've turned up at last.\r\nMind you, I ain't been 'ere long meself.", "Oh, vous v'là enfin.\r\nRemarquez, j'suis pas là depuis bien longtemps moi-même.");
                s = s.Replace("Hello again, Gina.", "Rebonjour, Gina.");
                s = s.Replace("Sholmes 'as only just left.\r\nYer lucky ya missed that.", "Holmes vient tout juste de décamper.\r\nVous avez du bol d'avoir raté ça.");
                s = s.Replace("'E went prancin' around in 'ere, pointin' at stuff an' flickin'\r\nthat 'at of 'is an' then just scarpered.", "Il s'est mis à sautiller partout, à pointer du doigt et à faire tournoyer son couvre-chef avant de filer à l'anglaise.");
                s = s.Replace("Oh! He's finished investigating already, you mean?", "Oh ! Vous voulez dire qu'il a déjà bouclé son enquête ?");
                s = s.Replace("Yeah... 'E didn't stop to say nuffin' to no one.\r\nNot even me.", "Ouais... Il a pas décroché un mot à personne.\r\nMême pas à moi.");
                s = s.Replace("Gina! Would you mind if we investigated, too?", "Gina ! Cela t'ennuierait si nous menions l'enquête nous aussi ?");
                s = s.Replace("Listen, 'Oddo... ...yer a lawyer, right?", "Écoute, Naruhodo... t'es avocat, pas vrai ?");
                s = s.Replace("Um...yes. Why?", "Euh... oui. Pourquoi ?");
                s = s.Replace("Well, yer not thinkin' of... tryin' to 'elp that Reaper bloke,\r\nare ya?", "Dis, tu songes pas à... essayer d'défendre ce gars du Faucheur, hein ?");
                s = s.Replace("Oh!\r\n(Poor Gina...)\r\n(She's never going to forget, is she?\r\nThat trial will haunt her forever.)", "Oh !\r\n(Pauvre Gina...)\r\n(Elle n'oubliera jamais, n'est-ce pas ?\r\nCe procès la hantera à tout jamais.)");
                s = s.Replace("Gina, if you don't mind me saying...\r\nIf Lord van Zieks really is responsible for this crime...\r\n...he will be duly and fairly judged in court.", "Gina, si je puis me permettre...\r\nSi Lord Van Peers est véritablement l'auteur de ce crime...\r\n... il sera équitablement et dûment jugé devant le tribunal.");
