                s = s.Replace("There are only two other men I've known with that same\r\nlook in their eyes:\r\nMy brother, Klint. ...And Genshin Asogi.", "Il n'y a que deux autres hommes que j'aie connus qui portaient cette même lueur dans le regard :\r\nMon frère, Klimt. ... Et Genshin Asogi.");
                s = s.Replace("(The man he idolised and the man who betrayed his trust\r\nin the most hideous way...)", "(L'homme qu'il vénérait et celui qui a trahi sa confiance de la façon la plus odieuse...)");
                s = s.Replace("When you showed me that photograph just now, it\r\nreminded me...", "Lorsque vous m'avez montré cette photographie à l'instant, cela m'a rappelé...");
